CAT = "afspFiling"; SEG = "FIL"
# AFTR outline 2.1 and 2.10: filing status, dependents (qualifying relative gross income limit,
# Rev. Proc. 2025-32 4.23) and the 2026 standard deduction (4.14). Pub. 501 rules. Tax year 2026.
_s67 = 16100 + 2050; assert _s67 == 18150
_mfj = 32200 + 2 * 1650; assert _mfj == 35500
_dep = max(1350, 5000 + 450); assert _dep == 5450
_hoh = 24150 + 2050; assert _hoh == 26200

Q = [
("For 2026, the standard deduction for a single filer age 67 who is not blind is:",
 f"${_s67:,}", ["$17,750", "$16,100", "$24,150"],
 "The 2026 basic amount for a single filer is $16,100, and an unmarried taxpayer 65 or older adds $2,050 (Rev. Proc. 2025-32, section 4.14): $18,150. $1,650 is the married add-on."),
("A married couple, both 66 and neither blind, file jointly for 2026. Their standard deduction is:",
 f"${_mfj:,}", ["$36,300", "$33,850", "$32,200"],
 "The 2026 joint amount is $32,200, plus $1,650 for each spouse 65 or older: $32,200 + $3,300 = $35,500. The $2,050 add-on is only for unmarried filers."),
("A student claimed as a dependent earned $5,000 from a summer job in 2026 and had no other income. Her standard deduction is:",
 f"${_dep:,}", ["$1,350", "$5,000", "$16,100"],
 "A dependent's 2026 standard deduction is the greater of $1,350 or earned income plus $450, but not more than the regular amount: $5,000 + $450 = $5,450."),
("Your mother had $6,000 of gross income in 2026, and you paid over half her support. Can you claim her as a qualifying relative?",
 "No, her income is too high", ["Yes, as a qualifying relative", "Yes, if she lives with you", "Yes, if she is over 65"],
 "A qualifying relative's 2026 gross income must be less than $5,300 (Rev. Proc. 2025-32, section 4.23). Support and residence do not cure income over the limit."),
("To file as head of household, an unmarried taxpayer must pay more than half the cost of:",
 "Keeping up the home", ["The child's schooling", "The household's food only", "The child's medical bills"],
 "Head of household needs more than half the cost of keeping up a home that is the main home of a qualifying person for over half the year, with parents an exception (Pub. 501)."),
("Ken's wife died in 2025. He has not remarried and keeps a home for his dependent son. He may file as a qualifying surviving spouse for:",
 "2026 and 2027", ["2025 and 2026", "2026 only", "2026 through 2028"],
 "In the year of death he can file jointly. With a dependent child he may then use qualifying surviving spouse status for the next two years, 2026 and 2027 (Pub. 501)."),
("A husband died in June 2026 and no executor was appointed. The couple's joint 2026 return is signed by:",
 "The surviving spouse", ["A court-appointed executor", "The couple's eldest child", "The paid preparer"],
 "If no personal representative has been appointed, the surviving spouse signs the joint return and writes \"filing as surviving spouse\" where the other spouse would sign (Pub. 559)."),
("Your 22-year-old son was a full-time student for five months of 2026. For the qualifying child age test, he:",
 "Qualifies as a student", ["Is too old", "Needs nine months of school", "Must earn under $5,300"],
 "A child under 24 at year end who was a full-time student during some part of each of five calendar months meets the age test (Pub. 501). The income limit applies to qualifying relatives, not qualifying children."),
("Unmarried parents both lived all year with their child, and both want to claim her. Under the tie-breaker rules, the claim goes to:",
 "The parent with higher AGI", ["The older parent", "The parent who paid more", "The parent named first"],
 "When parents who do not file jointly both claim the same child and the child lived with both for the same time, the parent with the higher AGI gets the claim (Pub. 501)."),
("With a signed Form 8332 from the custodial parent, the noncustodial parent can claim the child tax credit but not the child's:",
 "Earned income credit", ["Additional child tax credit", "Credit for other dependents", "Dependency claim"],
 "The release lets the noncustodial parent treat the child as a dependent for the child tax credit, additional child tax credit and credit for other dependents. The EIC, head of household and dependent care credit stay with the custodial parent (Pub. 501)."),
("Three siblings pay 40%, 35% and 25% of their father's support. Under a multiple support declaration, who may claim him?",
 "Any one of the three", ["Only the 40% sibling", "All three, each in part", "None of the siblings"],
 "No one paid over half, but together they did, and each paid over 10%. Any one of them can claim him if the others sign a statement agreeing not to (Form 2120)."),
("A head of household filer, age 70 and not blind, takes the 2026 standard deduction. It is:",
 f"${_hoh:,}", ["$25,800", "$24,150", "$18,150"],
 "The 2026 head of household amount is $24,150, and an unmarried filer 65 or older adds $2,050 (Rev. Proc. 2025-32, section 4.14): $26,200. $25,800 wrongly uses the $1,650 married add-on."),
("A divorce became final on December 31, 2026. For 2026 filing status, the taxpayer is:",
 "Unmarried for the year", ["Married for the year", "Married for half the year", "Married until filing"],
 "Marital status is decided on the last day of the tax year. A taxpayer divorced under a final decree by December 31 is unmarried for the whole year (Pub. 501)."),
("A married couple files separate 2026 returns and the wife itemizes. The husband's standard deduction is:",
 "$0", ["$16,100", "$8,050", "$32,200"],
 "If one spouse filing separately itemizes, the other cannot take the standard deduction and must itemize too, even if it gives a smaller deduction."),
("Which person must have lived with you all year as a household member to be your qualifying relative?",
 "A friend", ["Your mother", "Your nephew", "Your father-in-law"],
 "Relatives such as parents, in-laws, nieces and nephews need not live with you. Someone who is not related in a listed way, such as a friend, must live with you all year (Pub. 501)."),
("A single taxpayer pays over half the cost of keeping up her dependent father's own apartment. For head of household, her father:",
 "May live in his own home", ["Must live with her all year", "Must be under 65", "Must have no income"],
 "A parent is the exception to the shared-home rule. The taxpayer qualifies if she pays more than half the cost of the parent's main home and can claim the parent as a dependent (Pub. 501)."),
]
